import React, { useState } from 'react';
import { useLocalize } from '~/hooks';
import UserManagementTable from './UserApprovalTable';
import RolePermissionsTable from './RolePermissionsTable';
import SubscriptionPlansTable from './SubscriptionPlansTable';
import PromoCodesTable from './PromoCodesTable';
import PaymentAnalyticsDashboard from './PaymentAnalyticsDashboard';
import PushTestPanel from './PushTestPanel';
import MarketingPortal from './MarketingPortal';
// import TicketManagement from '~/components/Tickets/TicketManagement';
import { cn } from '~/utils';

export default function Admin() {
    const localize = useLocalize();
    const [activeTab, setActiveTab] = useState('users');

    // Listen for custom navigation events
    React.useEffect(() => {
        const handleSettingsNavigation = (e: CustomEvent) => {
            if (e.detail?.subTab) {
                setActiveTab(e.detail.subTab);
            }
        };
        window.addEventListener('switch-settings-tab', handleSettingsNavigation as EventListener);
        return () => {
            window.removeEventListener('switch-settings-tab', handleSettingsNavigation as EventListener);
        };
    }, []);

    return (
        <div className="flex flex-col gap-4 text-sm text-text-primary">
            {/* Tarjeta de Encabezado y Navegación */}
            <div className="rounded-2xl border border-gray-200 bg-surface-primary px-6 py-5 shadow-sm dark:border-gray-700">
                <div className="mb-4">
                    <h3 className="text-lg font-medium">{localize('com_ui_admin_panel')}</h3>
                    <p className="text-text-secondary">{localize('com_ui_admin_panel_description')}</p>
                </div>

                <div className="flex items-center justify-between overflow-x-auto pb-2 admin-nav-scrollbar" style={{ scrollbarWidth: 'none', msOverflowStyle: 'none' }}>
                    <style>{`
                        .admin-nav-scrollbar::-webkit-scrollbar { display: none; }
                        .custom-admin-scrollbar::-webkit-scrollbar {
                            height: 8px;
                            width: 8px;
                        }
                        .custom-admin-scrollbar::-webkit-scrollbar-track {
                            background: transparent;
                        }
                        .custom-admin-scrollbar::-webkit-scrollbar-thumb {
                            background: #cbd5e1;
                            border-radius: 9999px;
                        }
                        .dark .custom-admin-scrollbar::-webkit-scrollbar-thumb {
                            background: #4b5563;
                        }
                        .custom-admin-scrollbar::-webkit-scrollbar-thumb:hover {
                            background: #9ca3af;
                        }
                        .dark .custom-admin-scrollbar::-webkit-scrollbar-thumb:hover {
                            background: #6b7280;
                        }
                    `}</style>
                    <div className="flex space-x-4 whitespace-nowrap">
                        <button
                            onClick={() => setActiveTab('users')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'users'
                                    ? "border-b-2 border-blue-500 text-blue-600 dark:text-blue-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            {localize('com_ui_user_management')}
                        </button>
                        <button
                            onClick={() => setActiveTab('roles')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'roles'
                                    ? "border-b-2 border-blue-500 text-blue-600 dark:text-blue-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            {localize('com_ui_role_permissions')}
                        </button>
                        <button
                            onClick={() => setActiveTab('plans')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'plans'
                                    ? "border-b-2 border-green-500 text-green-600 dark:text-green-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            Planes y Suscripciones
                        </button>
                        <button
                            onClick={() => setActiveTab('promos')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'promos'
                                    ? "border-b-2 border-indigo-500 text-indigo-600 dark:text-indigo-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            Códigos Promo
                        </button>
                        <button
                            onClick={() => setActiveTab('analytics')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'analytics'
                                    ? "border-b-2 border-purple-500 text-purple-600 dark:text-purple-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            Analítica Pagos
                        </button>
                        <button
                            onClick={() => setActiveTab('push-test')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'push-test'
                                    ? "border-b-2 border-red-500 text-red-600 dark:text-red-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            Notificaciones Push
                        </button>
                        <button
                            onClick={() => setActiveTab('marketing')}
                            className={cn(
                                "pb-2 px-1 text-sm font-medium transition-colors duration-200",
                                activeTab === 'marketing'
                                    ? "border-b-2 border-pink-500 text-pink-600 dark:text-pink-400"
                                    : "text-text-secondary hover:text-text-primary"
                            )}
                        >
                            Mercadeo por Correo
                        </button>
                    </div>
                </div>
            </div>

            {/* Tarjeta de Contenido de la Tabla */}
            <div className="rounded-2xl border border-gray-200 bg-surface-primary px-6 py-5 shadow-sm dark:border-gray-700 overflow-hidden">
                {activeTab === 'users' ? (
                    <UserManagementTable />
                ) : activeTab === 'roles' ? (
                    <RolePermissionsTable />
                ) : activeTab === 'plans' ? (
                    <SubscriptionPlansTable />
                ) : activeTab === 'analytics' ? (
                    <PaymentAnalyticsDashboard />
                ) : activeTab === 'push-test' ? (
                    <PushTestPanel />
                ) : activeTab === 'marketing' ? (
                    <MarketingPortal />
                ) : (
                    <PromoCodesTable />
                )}
            </div>
        </div>
    );
}
