import React, { useState, useRef } from 'react';
import * as Tabs from '@radix-ui/react-tabs';
import { SettingsTabValues, SystemRoles } from 'librechat-data-provider';
import { MessageSquare, Command, DollarSign, Bell, TicketCheck } from 'lucide-react';
import { Dialog, DialogPanel, DialogTitle, Transition, TransitionChild } from '@headlessui/react';
import {
  GearIcon,
  DataIcon,
  UserIcon,
  SpeechIcon,
  useMediaQuery,
  PersonalizationIcon,
} from '@librechat/client';
import type { TDialogProps } from '~/common';
import {
  General,
  Chat,
  Commands,
  Speech,
  Personalization,
  Data,
  Balance,
  Account,
  Admin,
  Ads,
} from './SettingsTabs';
import NotificationsPage from '~/components/Notifications/NotificationsPage';
import TicketManagement from '~/components/Tickets/TicketManagement';
import { useAuthContext } from '~/hooks/AuthContext';
import usePersonalizationAccess from '~/hooks/usePersonalizationAccess';
import { useLocalize, TranslationKeys } from '~/hooks';
import { useGetStartupConfig } from '~/data-provider';
import { cn } from '~/utils';

export default function Settings({ open, onOpenChange, activeTab: initialTab }: TDialogProps & { activeTab?: SettingsTabValues | string }) {
  const isSmallScreen = useMediaQuery('(max-width: 767px)');
  const { data: startupConfig } = useGetStartupConfig();
  const { user } = useAuthContext();
  const localize = useLocalize();
  const [activeTab, setActiveTab] = useState<SettingsTabValues | string>(initialTab || SettingsTabValues.ACCOUNT);
  const [targetTicketId, setTargetTicketId] = useState<string | undefined>(undefined);

  React.useEffect(() => {
    if (open) {
      setActiveTab(initialTab || SettingsTabValues.ACCOUNT);
    }
  }, [open, initialTab]);

  const tabRefs = useRef({});
  const { hasAnyPersonalizationFeature, hasMemoryOptOut } = usePersonalizationAccess();

  // Listen for custom navigation events from child components
  React.useEffect(() => {
    const handleSettingsNavigation = (e: CustomEvent) => {
      if (e.detail?.mainTab) {
        setActiveTab(e.detail.mainTab);
      }
      if (e.detail?.ticketId) {
        setTargetTicketId(e.detail.ticketId);
      } else {
        setTargetTicketId(undefined);
      }
    };
    // Listen for programmatic open to jump to notifications
    const handleOpenSettings = () => {
      // no-op: settings is already open when this fires from notification click
    };
    window.addEventListener('switch-settings-tab', handleSettingsNavigation as EventListener);
    window.addEventListener('open-settings', handleOpenSettings as EventListener);
    return () => {
      window.removeEventListener('switch-settings-tab', handleSettingsNavigation as EventListener);
      window.removeEventListener('open-settings', handleOpenSettings as EventListener);
    };
  }, []);

  const handleKeyDown = (event: React.KeyboardEvent) => {
    const isAdmin = user?.role === SystemRoles.ADMIN;
    const tabs: (SettingsTabValues | string)[] = [
      SettingsTabValues.ACCOUNT,
      'notifications',
      SettingsTabValues.GENERAL,
      SettingsTabValues.DATA,
      ...(startupConfig?.balance?.enabled ? [SettingsTabValues.BALANCE] : []),
      ...(isAdmin
        ? [
          SettingsTabValues.CHAT,
          SettingsTabValues.COMMANDS,
          SettingsTabValues.SPEECH,
          ...(hasAnyPersonalizationFeature ? [SettingsTabValues.PERSONALIZATION] : []),
          'tickets',
          SettingsTabValues.ADMIN,
          'ads',
        ]
        : []),
    ];
    const currentIndex = tabs.indexOf(activeTab);

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();
        setActiveTab(tabs[(currentIndex + 1) % tabs.length]);
        break;
      case 'ArrowUp':
        event.preventDefault();
        setActiveTab(tabs[(currentIndex - 1 + tabs.length) % tabs.length]);
        break;
      case 'Home':
        event.preventDefault();
        setActiveTab(tabs[0]);
        break;
      case 'End':
        event.preventDefault();
        setActiveTab(tabs[tabs.length - 1]);
        break;
    }
  };

  const settingsTabs: {
    value: SettingsTabValues | string;
    icon: React.JSX.Element;
    label: TranslationKeys;
  }[] = [
      {
        value: SettingsTabValues.ACCOUNT,
        icon: <UserIcon />,
        label: 'com_nav_setting_account',
      },
      {
        value: 'notifications',
        icon: <Bell className="icon-sm" />,
        label: 'Notificaciones' as TranslationKeys,
      },
      {
        value: SettingsTabValues.GENERAL,
        icon: <GearIcon />,
        label: 'com_nav_setting_general',
      },
      {
        value: SettingsTabValues.DATA,
        icon: <DataIcon />,
        label: 'com_nav_setting_data',
      },
      ...(startupConfig?.balance?.enabled
        ? [
          {
            value: SettingsTabValues.BALANCE,
            icon: <DollarSign size={18} />,
            label: 'com_nav_setting_balance' as TranslationKeys,
          },
        ]
        : []),
      ...(user?.role === SystemRoles.ADMIN
        ? [
          {
            value: SettingsTabValues.CHAT,
            icon: <MessageSquare className="icon-sm" />,
            label: 'com_nav_setting_chat',
          },
          {
            value: SettingsTabValues.COMMANDS,
            icon: <Command className="icon-sm" />,
            label: 'com_nav_commands',
          },
          {
            value: SettingsTabValues.SPEECH,
            icon: <SpeechIcon className="icon-sm" />,
            label: 'com_nav_setting_speech',
          },
          ...(hasAnyPersonalizationFeature
            ? [
              {
                value: SettingsTabValues.PERSONALIZATION,
                icon: <PersonalizationIcon />,
                label: 'com_nav_setting_personalization' as TranslationKeys,
              },
            ]
            : []),
          {
            value: 'tickets',
            icon: <TicketCheck className="icon-sm" />,
            label: 'Tickets PQRS' as TranslationKeys,
          },
          {
            value: SettingsTabValues.ADMIN,
            icon: <GearIcon />,
            label: 'Admin' as TranslationKeys,
          },
          {
            value: 'ads',
            icon: <DollarSign className="icon-sm" />,
            label: 'Ads' as TranslationKeys,
          },
        ]
        : []),
    ];

  const handleTabChange = (value: string) => {
    setActiveTab(value as SettingsTabValues);
  };

  return (
    <Transition appear show={open}>
      <Dialog as="div" className="relative z-50" onClose={onOpenChange}>
        <TransitionChild
          enter="ease-out duration-200"
          enterFrom="opacity-0"
          enterTo="opacity-100"
          leave="ease-in duration-200"
          leaveFrom="opacity-100"
          leaveTo="opacity-0"
        >
          <div className="fixed inset-0 bg-black opacity-50 dark:opacity-80" aria-hidden="true" />
        </TransitionChild>

        <TransitionChild
          enter="ease-out duration-200"
          enterFrom="opacity-0 scale-95"
          enterTo="opacity-100 scale-100"
          leave="ease-in duration-100"
          leaveFrom="opacity-100 scale-100"
          leaveTo="opacity-0 scale-95"
        >
          <div className={cn('fixed inset-0 flex w-screen items-center justify-center p-4')}>
            <DialogPanel
              className={cn(
                'min-h-[450px] overflow-hidden rounded-xl rounded-b-lg bg-background pb-6 shadow-2xl backdrop-blur-2xl animate-in sm:rounded-2xl md:min-h-[450px] md:w-[900px]',
              )}
            >
              <DialogTitle
                className="mb-1 flex items-center justify-between p-6 pb-5 text-left"
                as="div"
              >
                <h2 className="text-lg font-medium leading-6 text-text-primary">
                  {localize('com_nav_settings')}
                </h2>
                <button
                  type="button"
                  className="rounded-sm opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-border-xheavy focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-surface-primary dark:focus:ring-offset-surface-primary"
                  onClick={() => onOpenChange(false)}
                >
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="24"
                    height="24"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    className="h-5 w-5 text-text-primary"
                  >
                    <line x1="18" x2="6" y1="6" y2="18"></line>
                    <line x1="6" x2="18" y1="6" y2="18"></line>
                  </svg>
                  <span className="sr-only">{localize('com_ui_close_settings')}</span>
                </button>
              </DialogTitle>
              <div className="max-h-[550px] overflow-auto px-6 md:max-h-[550px] md:min-h-[450px] md:w-[900px]">
                <Tabs.Root
                  value={activeTab}
                  onValueChange={handleTabChange}
                  className="flex flex-col gap-10 md:flex-row"
                  orientation="vertical"
                >
                  <Tabs.List
                    aria-label="Settings"
                    className={cn(
                      'min-w-auto max-w-auto relative -ml-[8px] flex flex-shrink-0 flex-col flex-nowrap overflow-auto sm:max-w-none',
                      isSmallScreen
                        ? 'flex-row rounded-xl bg-surface-secondary'
                        : 'sticky top-0 h-full',
                    )}
                    onKeyDown={handleKeyDown}
                  >
                    {settingsTabs.map(({ value, icon, label }) => (
                      <Tabs.Trigger
                        key={value}
                        className={cn(
                          'group relative z-10 m-1 flex items-center justify-start gap-2 rounded-xl px-2 py-1.5 transition-all duration-200 ease-in-out',
                          isSmallScreen
                            ? 'flex-1 justify-center text-nowrap p-1 px-3 text-sm text-text-secondary radix-state-active:bg-surface-hover radix-state-active:text-text-primary'
                            : 'bg-transparent text-text-secondary radix-state-active:bg-surface-tertiary radix-state-active:text-text-primary',
                        )}
                        value={value}
                        ref={(el) => (tabRefs.current[value] = el)}
                      >
                        {icon}
                        {localize(label)}
                      </Tabs.Trigger>
                    ))}
                  </Tabs.List>
                  <div className="overflow-auto sm:w-full sm:max-w-none md:pr-0.5 md:pt-0.5">
                    <Tabs.Content value={SettingsTabValues.GENERAL} tabIndex={-1}>
                      <General />
                    </Tabs.Content>
                    <Tabs.Content value={SettingsTabValues.CHAT} tabIndex={-1}>
                      <Chat />
                    </Tabs.Content>
                    <Tabs.Content value={SettingsTabValues.COMMANDS} tabIndex={-1}>
                      <Commands />
                    </Tabs.Content>
                    <Tabs.Content value={SettingsTabValues.SPEECH} tabIndex={-1}>
                      <Speech />
                    </Tabs.Content>
                    {hasAnyPersonalizationFeature && (
                      <Tabs.Content value={SettingsTabValues.PERSONALIZATION} tabIndex={-1}>
                        <Personalization
                          hasMemoryOptOut={hasMemoryOptOut}
                          hasAnyPersonalizationFeature={hasAnyPersonalizationFeature}
                        />
                      </Tabs.Content>
                    )}
                    <Tabs.Content value={SettingsTabValues.DATA} tabIndex={-1}>
                      <Data />
                    </Tabs.Content>
                    {startupConfig?.balance?.enabled && (
                      <Tabs.Content value={SettingsTabValues.BALANCE} tabIndex={-1}>
                        <Balance />
                      </Tabs.Content>
                    )}
                    <Tabs.Content value={SettingsTabValues.ACCOUNT} tabIndex={-1}>
                      <Account />
                    </Tabs.Content>
                    {user?.role === SystemRoles.ADMIN && (
                      <Tabs.Content value={SettingsTabValues.ADMIN} tabIndex={-1}>
                        <Admin />
                      </Tabs.Content>
                    )}
                    {user?.role === SystemRoles.ADMIN && (
                      <Tabs.Content value={'ads'} tabIndex={-1}>
                        <Ads />
                      </Tabs.Content>
                    )}
                    <Tabs.Content value={'notifications'} tabIndex={-1}>
                      <NotificationsPage />
                    </Tabs.Content>
                    <Tabs.Content value={'tickets'} tabIndex={-1}>
                      <TicketManagement initialTicketId={targetTicketId} />
                    </Tabs.Content>
                  </div>
                </Tabs.Root>
              </div>
            </DialogPanel>
          </div>
        </TransitionChild>
      </Dialog>
    </Transition>
  );
}
